def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    edge_colors = set(grid[0]) | set(grid[-1]) | {grid[r][0] for r in range(h)} | {grid[r][-1] for r in range(h)}
    interior_colors = {v for row in grid for v in row if v != bg and v not in edge_colors}
    # The lone interior color is the ray color; existing cells of this color
    # are targets that become 4 when reached by a ray.
    ray = next(iter(interior_colors)) if len(interior_colors) == 1 else None
    out = [row[:] for row in grid]
    if ray is None:
        return out

    def shoot(r, c, dr, dc):
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] == ray:
                out[rr][cc] = 4
                break
            if grid[rr][cc] != bg:
                break
            out[rr][cc] = ray
            rr += dr
            cc += dc

    # Every run of a non-background border color sends perpendicular rays
    # inward from its two endpoints.
    for r in (0, h - 1):
        row = grid[r]
        c = 0
        while c < w:
            color = row[c]
            e = c + 1
            while e < w and row[e] == color:
                e += 1
            if color != bg and e - c >= 2:
                dr = 1 if r == 0 else -1
                shoot(r, c, dr, 0)
                if e - 1 != c:
                    shoot(r, e - 1, dr, 0)
            c = e
    for c in (0, w - 1):
        r = 0
        while r < h:
            color = grid[r][c]
            e = r + 1
            while e < h and grid[e][c] == color:
                e += 1
            if color != bg and e - r >= 2:
                dc = 1 if c == 0 else -1
                shoot(r, c, 0, dc)
                if e - 1 != r:
                    shoot(e - 1, c, 0, dc)
            r = e
    return out
